variante_1.js:
document.addEventListener('DOMContentLoaded', function() {
  const toastEl = document.getElementById('liveToast');
  if (toastEl) {
    const toast = new bootstrap.Toast(toastEl, {
      delay: 5000 // 5 segundos
    });
    // Para demonstração, o toast é exibido automaticamente ao carregar a página.
    // Em um cenário real, você o mostraria com base em uma ação do usuário ou evento específico.
    toast.show();
  }
});

