  border-radius: var(--bs-border-radius);
  --bs-alert-bg: rgba(var(--sl-accent-rgb), 0.1);
  --bs-alert-border-color: var(--sl-accent);
  --bs-alert-color: var(--sl-text-main);
}
#sessionStorageAlert .btn-close {
  filter: invert(var(--bs-btn-close-color-dark, 0)); /* Ajusta a cor do botão de fechar para contraste em temas escuros */
}

variante_3.js:
document.addEventListener('DOMContentLoaded', function() {
  const alertId = 'sessionStorageAlert';
  const alertElement = document.getElementById(alertId);
  const storageKey = 'dismissed_' + alertId;

  if (alertElement) {
    // Verifica se o alerta foi dismissido na sessão atual
    if (sessionStorage.getItem(storageKey) === 'true') {
      alertElement.classList.add('d-none'); // Esconde o alerta se já foi dismissido
    } else {
      alertElement.classList.remove('d-none'); // Garante que o alerta esteja visível se não foi dismissido
    }

    // Adiciona um listener para quando o alerta for fechado
    alertElement.addEventListener('closed.bs.alert', function () {
      sessionStorage.setItem(storageKey, 'true'); // Salva o estado no sessionStorage
    });
  }
});

